import{_ as t,o as r,c as i,ah as a}from"./chunks/framework.DDXs_i7t.js";const u=JSON.parse('{"title":"Logbuch: Gerechtigkeit am Peršmanhof – Sieg gegen die Hydra","description":"","frontmatter":{},"headers":[],"relativePath":"logbuch/2026-04-16-persmanhof-victory.md","filePath":"logbuch/2026-04-16-persmanhof-victory.md"}'),n={name:"logbuch/2026-04-16-persmanhof-victory.md"};function s(h,e,o,g,d,c){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="logbuch-gerechtigkeit-am-persmanhof-–-sieg-gegen-die-hydra" tabindex="-1">Logbuch: Gerechtigkeit am Peršmanhof – Sieg gegen die Hydra <a class="header-anchor" href="#logbuch-gerechtigkeit-am-persmanhof-–-sieg-gegen-die-hydra" aria-label="Permalink to &quot;Logbuch: Gerechtigkeit am Peršmanhof – Sieg gegen die Hydra&quot;">​</a></h1><p><strong>Datum:</strong> 16. April 2026 <strong>Status:</strong> Meilenstein der Rechtsstaatlichkeit</p><h2 id="🏛️-der-heutige-gerichtsbeschluss" tabindex="-1">🏛️ Der heutige Gerichtsbeschluss <a class="header-anchor" href="#🏛️-der-heutige-gerichtsbeschluss" aria-label="Permalink to &quot;🏛️ Der heutige Gerichtsbeschluss&quot;">​</a></h2><p>Das Landesverwaltungsgericht Kärnten hat heute entschieden: Die Identitätsfeststellungen der Polizei am Peršmanhof waren <strong>rechtswidrig</strong>. Dies ist ein gewaltiger Schlag gegen die Willkür des Staatsschutzes, der unter dem Deckmantel des Naturschutzes (illegales Camping) ein antifaschistisches Camp schikaniert hat.</p><h2 id="🔗-die-verbindung-zum-projekt" tabindex="-1">🔗 Die Verbindung zum Projekt <a class="header-anchor" href="#🔗-die-verbindung-zum-projekt" aria-label="Permalink to &quot;🔗 Die Verbindung zum Projekt&quot;">​</a></h2><p>In unserem Filmprojekt „Das Horten-Mysterium“ wird der Fall Peršmanhof zu einem zentralen Motiv für die <strong>Kontinuität staatlicher Übergriffigkeit</strong>:</p><ol><li><strong>1945:</strong> SS/Gestapo-Massaker an der Familie Sadovnik.</li><li><strong>2025:</strong> „Staatsschutz“-Einsatz mit Hubschraubern und SIG-Einheiten gegen Gedenkende.</li><li><strong>2026:</strong> Das Gericht entlarvt den Einsatz als das, was er war: Machtmissbrauch ohne Rechtsgrundlage.</li></ol><h2 id="⚖️-fazit" tabindex="-1">⚖️ Fazit <a class="header-anchor" href="#⚖️-fazit" aria-label="Permalink to &quot;⚖️ Fazit&quot;">​</a></h2><p>Während Politiker wie August Wöginger vor Gericht behaupten, ihre Interventionen seien „Bürgernähe“, zeigt der Fall Peršmanhof das wahre Gesicht der „Hydra“: Die Einschüchterung derer, die sich an die dunklen Seiten der Macht erinnern.</p><p><strong>Update:</strong> Das Drehbuch (Teil 4) wurde um die Szene „Das Echo vom Peršmanhof“ ergänzt, um diese historische Linie sichtbar zu machen.</p>',10)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
